// A won deal means that company now banks with Mercury, so it belongs in
// existing_mercury_customers and the dedupe must remove it the next time it
// files a Form D. Without this the table only ever holds what was seeded by
// hand, and the flywheel does not turn.
//
// Domain and CIK are read off the organization's custom fields, which is why
// they were put on the organization rather than the deal: they outlive it.
const DOMAIN_KEY = 'f74ce5e0ca0db0f38abe652c19a5a6013e42f6ba';
const out = [];
for (const item of $input.all()) {
  for (const deal of (item.json.data || [])) {
    const org = deal.org_id || {};
    const domain = org[DOMAIN_KEY] || deal[DOMAIN_KEY];
    if (!domain) continue;
    out.push({ json: {
      company_name: org.name || deal.title,
      domain: String(domain).toLowerCase(),
      contact_name: (deal.person_id && deal.person_id.name) || null,
      source_deal_id: deal.id,
    }});
  }
}
return out;
